package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import java.util.Objects;
import org.bukkit.entity.Creeper;
import org.bukkit.entity.Vex;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.inventory.EntityEquipment;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemType;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class GhostCreeperBehaviour implements CompiledBehaviour {
    private static final EntityDamageEvent.DamageCause SUFFOCATION = EntityDamageEvent.DamageCause.SUFFOCATION;

    private static final EquipmentSlot HAND = EquipmentSlot.HAND;

    private static final ItemType AIR = Registries.entry(RegistryKey.ITEM, "minecraft:air");

    private static final EquipmentSlot OFF_HAND = EquipmentSlot.OFF_HAND;

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final PotionEffectType SPEED = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:speed");

    private final MobContext context;

    private Cooldown cooldown;

    public GhostCreeperBehaviour(MobContext context) {
        this.context = context;
        // node #63 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onDamage(EntityDamageEvent event) {
        // node #6 event.damage
        // node #8 flow.branch
        if (!(Objects.equals(event.getCause(), SUFFOCATION))) return;
        // node #7 cancellable.mutate
        event.setCancelled(true);
        // node #9
    }

    @Override
    public void onExplode(EntityExplodeEvent event) {
        // node #16 event.explode
        // node #19 flow.branch
        // node #17 mob.extension
        final Vex extension = ((Vex) this.context.extension());
        if (extension == null) return;
        // node #18 entity.remove
        extension.remove();
        // node #20
    }

    @Override
    public void onExtensionDamage(EntityDamageEvent event) {
        // node #27 event.extension_damage
        // node #29 flow.branch
        if (!(Objects.equals(event.getCause(), SUFFOCATION))) return;
        // node #28 cancellable.mutate
        event.setCancelled(true);
        // node #30
    }

    @Override
    public void onExtensionDeath(EntityDeathEvent event) {
        // node #38 event.extension_death
        // node #41 flow.branch
        // node #39 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        if (self.isDead()) return;
        // node #40 living_entity.damage
        self.damage(self.getHealth());
        // node #42
    }

    @Override
    public void onSpawn() {
        // node #54 mob.spawn
        // node #60 flow.branch
        // node #55 mob.extension
        final Vex extension = ((Vex) this.context.extension());
        if (extension == null) return;
        // node #56 mob.mutate
        extension.setInvisible(true);
        // node #58 equipment.equip
        // node #57 mob.read
        final EntityEquipment equipment = extension.getEquipment();
        equipment.setItem(HAND, AIR.createItemStack());
        // node #59 equipment.equip
        equipment.setItem(OFF_HAND, AIR.createItemStack());
        // node #61
    }

    @Override
    public void onTick() {
        // node #69 mob.tick
        // node #72 flow.branch
        // node #70 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(30000.0d));
        if (!cooldown) return;
        // node #71 living_entity.apply_effect
        ((Creeper) this.context.entity()).addPotionEffect(new PotionEffect(SPEED, (int) (60.0d * 20), 4, false, false));
        // node #73
    }
}
